const servers = [
  { name: 'Production', host: 'prod.example.com', sshUser: 'admin' },
  { name: 'Staging', host: 'staging.example.com', sshUser: 'admin' }
];
return servers.map(s => ({ json: s }));

const items = $input.all();
const results = [];
for (const item of items) {
  const data = item.json;
  const cpuUsage = data.cpu || Math.random() * 100;
  const ramUsage = data.ram || Math.random() * 100;
  const diskUsage = data.disk || Math.random() * 100;
  const uptime = data.uptime || '0d 0h';

  const cpuCritical = cpuUsage > 90;
  const ramCritical = ramUsage > 85;
  const diskCritical = diskUsage > 90;
  const isCritical = cpuCritical || ramCritical || diskCritical;

  results.push({
    json: {
      serverName: item.json.name || 'Server',
      host: item.json.host || '',
      cpu: cpuUsage.toFixed(1),
      ram: ramUsage.toFixed(1),
      disk: diskUsage.toFixed(1),
      uptime,
      cpuCritical,
      ramCritical,
      diskCritical,
      isCritical,
      status: isCritical ? 'CRITICAL' : 'OK',
      timestamp: new Date().toISOString(),
      date: new Date().toISOString().split('T')[0]
    }
  });
}
return results;

